DROP TABLE IF EXISTS `ai_gen_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_gen_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `biz_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型：PLAN_GEN/EFFECT_DIAG/RETRAIN/QA/PAPER_GEN/JUDGE',
  `biz_id` bigint DEFAULT NULL COMMENT '关联业务ID（如计划ID、考试记录ID）',
  `user_id` bigint DEFAULT NULL COMMENT '触发用户',
  `template_id` bigint DEFAULT NULL COMMENT '使用的 Prompt 模板',
  `input_snapshot` json DEFAULT NULL COMMENT '输入快照（差距表等），保证可复现',
  `retrieved_chunks` json DEFAULT NULL COMMENT '检索命中的知识片段ID与相似度，用于有/无RAG对比',
  `output_content` longtext COLLATE utf8mb4_general_ci COMMENT '模型原始输出',
  `parsed_output` json DEFAULT NULL COMMENT '解析校验后的结构化结果',
  `model` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `prompt_tokens` int DEFAULT NULL,
  `completion_tokens` int DEFAULT NULL,
  `cost_ms` int DEFAULT NULL COMMENT '耗时（毫秒），性能指标',
  `attempt_count` int NOT NULL DEFAULT '1' COMMENT '尝试次数（含重试）',
  `gen_mode` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成模式：RULE/HYBRID/LLM_ONLY，三组对比实验的分组键',
  `hallucination_count` int DEFAULT NULL COMMENT '幻觉课程数（仅 LLM_ONLY 有意义）',
  `blind_score` tinyint DEFAULT NULL COMMENT '盲评得分 1-5（人工在不知模式的条件下打分）',
  `status` varchar(24) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'SUCCESS' COMMENT '状态：SUCCESS成功/SCHEMA_FAILED结构校验失败/RETRIED重试/FALLBACK降级为规则方案/API_ERROR接口异常',
  `adopt_status` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '人工采纳情况：PENDING待确认/ADOPTED采纳/MODIFIED修改后采纳/REJECTED驳回',
  `reject_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_biz` (`biz_type`,`biz_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create` (`create_time`),
  KEY `idx_gen_mode` (`gen_mode`)
) ENGINE=InnoDB AUTO_INCREMENT=269 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI 生成记录表（结构合规率、采纳率、耗时等实验指标的数据来源）';
