INSERT INTO `ai_gen_record` VALUES (239,'PLAN_GEN',NULL,5,1,'{\"mode\": \"LLM_ONLY\", \"items\": [{\"gap\": 1, \"weight\": 1.0, \"skillId\": 8, \"assessed\": true, \"category\": \"技术\", \"skillName\": \"质量检验与测量\", \"targetLevel\": 3, \"weightedGap\": 1.0, \"currentLevel\": 2, \"priorityRank\": 1, \"priorityLevel\": \"高\", \"priorityScore\": 100.0}, {\"gap\": 1, \"weight\": 0.8, \"skillId\": 14, \"assessed\": true, \"category\": \"通用\", \"skillName\": \"团队协作\", \"targetLevel\": 3, \"weightedGap\": 0.8, \"currentLevel\": 2, \"priorityRank\": 2, \"priorityLevel\": \"高\", \"priorityScore\": 80.0}, {\"gap\": 0, \"weight\": 1.5, \"skillId\": 1, \"assessed\": true, \"category\": \"安全\", \"skillName\": \"安全生产规范\", \"targetLevel\": 4, \"weightedGap\": 0.0, \"currentLevel\": 4, \"priorityRank\": null, \"priorityLevel\": \"已达标\", \"priorityScore\": 0}, {\"gap\": 0, \"weight\": 1.5, \"skillId\": 5, \"assessed\": true, \"category\": \"技术\", \"skillName\": \"设备操作与标准化作业\", \"targetLevel\": 4, \"weightedGap\": 0.0, \"currentLevel\": 4, \"priorityRank\": null, \"priorityLevel\": \"已达标\", \"priorityScore\": 0}, {\"gap\": 0, \"weight\": 1.0, \"skillId\": 6, \"assessed\": true, \"category\": \"技术\", \"skillName\": \"设备维护保养\", \"targetLevel\": 3, \"weightedGap\": 0.0, \"currentLevel\": 3, \"priorityRank\": null, \"priorityLevel\": \"已达标\", \"priorityScore\": 0}, {\"gap\": 0, \"weight\": 0.8, \"skillId\": 18, \"assessed\": true, \"category\": \"管理\", \"skillName\": \"流程制度执行\", \"targetLevel\": 3, \"weightedGap\": 0.0, \"currentLevel\": 3, \"priorityRank\": null, \"priorityLevel\": \"已达标\", \"priorityScore\": 0}], \"userId\": 5, \"postName\": \"生产操作工\", \"realName\": \"李四\", \"matchRate\": 92.11, \"ruleCourses\": []}','[{\"docId\": 22, \"score\": 1.0, \"source\": \"公司岗位体系文件\", \"chunkId\": 45, \"content\": \"质量检验员需达到质量检验与测量等级 5、缺陷判定与原因分析等级 4；质量工程师进一步要求生产数据分析等级 4 与技术文档写作等级 4，能独立主导质量改进项目。\", \"docName\": \"《关键岗位说明书汇编》\", \"docType\": \"POST_DESC\"}, {\"docId\": 8, \"score\": 0.7111, \"source\": \"企业岗位技能标准（内部资料）\", \"chunkId\": 15, \"content\": \"质量检验与测量（技术类，等级 1-5）：掌握检验标准、量具使用、抽样方法与检验记录规范。等级 1 为知晓基本概念；等级 2 为能在指导下完成；等级 3 为能独立完成常规作业；等级 4 为能处理复杂与异常场景并指导他人；等级 5 为能制定标准、开展改进与培训。岗位达标要求由岗位技能要求表确定。\", \"docName\": \"《技术岗位技能标准》质量检验与测量\", \"docType\": \"SKILL_STANDARD\"}, {\"docId\": 8, \"score\": 0.6433, \"source\": \"企业岗位技能标准（内部资料）\", \"chunkId\": 16, \"content\": \"培训与考核建议：针对「质量检验与测量」等级提升，建议先安排基础课程建立概念，再通过现场实操与案例研讨强化，最后以题库测验（含简答题）验证。培训后等级提升 1 级以上视为有效，未达标者进入补训环节。\", \"docName\": \"《技术岗位技能标准》质量检验与测量\", \"docType\": \"SKILL_STANDARD\"}, {\"docId\": 22, \"score\": 0.5988, \"source\": \"公司岗位体系文件\", \"chunkId\": 44, \"content\": \"生产操作工：负责产线设备操作、产品自检与现场 5S，需达到安全生产规范等级 4、设备操作与标准化作业等级 4。班组长在此基础上还需具备危险源辨识等级 4 与现场管理带教等级 4。\", \"docName\": \"《关键岗位说明书汇编》\", \"docType\": \"POST_DESC\"}, {\"docId\": 14, \"score\": 0.5653, \"source\": \"企业岗位技能标准（内部资料）\", \"chunkId\": 27, \"content\": \"团队协作（通用类，等级 1-5）：跨班组沟通、任务协同、交接班信息传递与冲突处理。等级 1 为知晓基本概念；等级 2 为能在指导下完成；等级 3 为能独立完成常规作业；等级 4 为能处理复杂与异常场景并指导他人；等级 5 为能制定标准、开展改进与培训。岗位达标要求由岗位技能要求表确定。\", \"docName\": \"《通用岗位技能标准》团队协作\", \"docType\": \"SKILL_STANDARD\"}]','{\"summary\":\"针对李四质量检验与测量（差距1级、权重1.00）与团队协作（差距1级、权重0.80）两项高优先级差距，结合生产操作工岗位对安全与设备操作的基础要求，方案先补质量检验与测量，再补团队协作，并穿插安全生产与设备操作基础课程以夯实岗位底线。总学时控制在40学时以内，课程按差距优先级与技能依赖关系排序，每门课均说明安排依据。\",\"totalHours\":38,\"courses\":[{\"courseId\":12,\"courseName\":\"质量检验与测量基础\",\"seqNo\":1,\"hours\":6,\"coverSkill\":\"质量检验与测量\",\"gapBefore\":1,\"reason\":\"该课程直接对应第1优先级差距（质量检验与测量，当前2级→目标3级，加权差距1.00）。知识库片段2指出等级2为能在指导下完成、等级3为能独立完成常规作业，本课程等级2可系统补齐检验标准、量具使用、抽样方法与检验记录规范，为后续现场实操与等级提升打基础；片段3建议先安排基础课程建立概念，故列为第一门。\"},{\"courseId\":13,\"courseName\":\"缺陷判定与原因分析基础\",\"seqNo\":2,\"hours\":4,\"coverSkill\":\"缺陷判定与原因分析\",\"gapBefore\":0,\"reason\":\"质量检验与测量等级3要求能独立完成常规作业并处理检验结果，缺陷判定与原因分析是其直接支撑技能。知识库片段1显示质量检验相关岗位对缺陷判定有明确等级要求，本课程等级2可帮助李四在完成检验后正确判定缺陷并初步分析原因，巩固第1优先级技能的应用能力，故紧随质量检验基础之后安排。\"},{\"courseId\":21,\"courseName\":\"团队协作基础\",\"seqNo\":3,\"hours\":4,\"coverSkill\":\"团队协作\",\"gapBefore\":1,\"reason\":\"该课程直接对应第2优先级差距（