--
-- Table structure for table `ai_prompt_template`
--

DROP TABLE IF EXISTS `ai_prompt_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_prompt_template` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `template_code` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板编码',
  `template_name` varchar(128) COLLATE utf8mb4_general_ci NOT NULL,
  `scene` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '场景：PLAN_GEN方案生成/EFFECT_DIAG效果诊断/RETRAIN补训方案/QA知识问答/PAPER_GEN组卷/JUDGE主观题评分',
  `content` text COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Prompt 模板正文，用 {{变量}} 占位',
  `system_content` text COLLATE utf8mb4_general_ci COMMENT '系统提示词，与 content（用户提示词）分离管理，避免硬编码在 Java 里',
  `input_schema` json DEFAULT NULL COMMENT '期望输入的变量说明与校验规则',
  `output_schema` json DEFAULT NULL COMMENT '期望输出的 JSON 结构，用于校验',
  `model` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'deepseek-chat' COMMENT '使用的模型名称',
  `temperature` decimal(3,2) NOT NULL DEFAULT '0.30',
  `max_tokens` int DEFAULT NULL,
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号，便于版本对比实验',
  `status` tinyint NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_version` (`template_code`,`version`),
  KEY `idx_scene` (`scene`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Prompt 模板表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ai_prompt_template`
--

/*!40000 ALTER TABLE `ai_prompt_template` DISABLE KEYS */;
INSERT INTO `ai_prompt_template` VALUES (1,'PLAN_GEN_V1','个性化培训方案生成','PLAN_GEN','你是一名企业培训专家。请根据下面的员工技能差距数据与候选课程清单，生成个性化培训方案。\n\n【员工信息】\n姓名：{{realName}}；岗位：{{postName}}；部门：{{deptName}}\n\n【技能差距（已按优先级排序，gap=目标等级-当前等级，priority=gap×权重）】\n{{gapTable}}\n\n【候选课程（已由规则引擎按差距优先级召回，课程ID不可虚构）】\n{{courseCandidates}}\n\n【知识库依据】\n{{ragContext}}\n\n【要求】\n1. 只能从候选课程中选择，courseId 必须来自候选清单；\n2. 按 gap 从大到小安排学习顺序，先补高权重差距；\n3. 总学时控制在 {{totalHours}} 学时以内；\n4. 每门课必须给出 reason，说明它解决哪个技能差距、依据是什么；\n5. 输出严格为 JSON，不要任何解释性文字或 Markdown 代码块。\n\n【输出格式】\n{\"summary\":\"方案总体说明，150字以内\",\"totalHours\":数字,\"courses\":[{\"courseId\":数字,\"seqNo\":数字,\"hours\":数字,\"coverSkill\":\"技能名称\",\"gapBefore\":数字,\"reason\":\"安排依据\"}]}','你是企业培训方案设计专家。你只能从给定的候选课程中选择，输出必须是合法 JSON，不要输出任何解释性文字、Markdown 代码块或注释。',NULL,NULL,'deepseek-chat',0.30,2000,1,1,'2026-10-17 11:34:21','2026-11-25 21:21:35',0),(2,'EFFECT_DIAG_V1','培训效果诊断','EFFECT_DIAG','你是一名培训效果评估专家。请根据以下数据给出效果诊断结论。\n\n【员工】{{realName}}（{{postName}}）\n【培训计划】{{planName}}\n【前测成绩】{{preScore}}  【后测成绩】{{postScore}}  【提升】{{improve}}\n【计划完成率】{{finishRate}}%\n【培训前技能差距】{{gapBefore}}\n【培训后技能差距】{{gapAfter}}\n【差距缩小率】{{gapReduce}}%\n\n【要求】培训等级由系统依据分数阈值判定，已给出结论；你不要自行判定等级，诊断文字中不要出现「优秀」「达标」「未达标」「合格」等结论性等级词。请聚焦三点：本次培训是否产生实际效果（用数据说明）、仍存在的主要短板及其业务影响、2-3 条具体改进建议。\n输出 JSON：{\"diagnosis\":\"诊断结论，200字以内，只描述数据与短板，不含等级判定\",\"weakPoints\":[\"短板1\",\"短板2\"],\"suggestions\":[\"建议1\",\"建议2\"]}','你是培训效果评估专家，只输出 JSON。',NULL,NULL,'deepseek-chat',0.20,1200,1,1,'2026-10-17 11:34:21','2026-11-27 18:39:33',0),(4,'QA_V1','知识库问答','QA','你是企业培训知识助手。请仅依据下面检索到的知识片段回答用户问题，不要编造。\n\n【知识片段】\n{{ragContext}}\n\n【用户问题】{{question}}\n\n【要求】回答简洁准确；若知识片段不足以回答，明确说明\"知识库中未收录该内容\"，不要猜测。\n在回答末尾用「参考：文档名」标注引用来源。','你是企业培训知识助手，回答必须基于给定资料，不得编造。',NULL,NULL,'deepseek-chat',0.10,1000,1,1,'2026-10-17 11:34:21','2026-11-25 21:21:35',0),(6,'JUDGE_V1','主观题辅助评分','JUDGE','你是严谨的阅卷老师，请为简答题评分。\n\n【题目】{{question}}\n【参考答案】{{answer}}\n【评分要点】{{analysis}}\n【满分】{{fullScore}}\n【学员作答】{{userAnswer}}\n\n【要求】按参考要点给分，允许同义表述；给分需保守客观。输出 JSON：\n{\"score\":数字,\"reason\":\"评分理由，80字以内\",\"missing\":\"遗漏的要点\"}','你是严谨的阅卷老师，只输出 JSON。',NULL,NULL,'deepseek-chat',0.10,600,1,1,'2026-10-17 11:34:21','2026-11-25 21:21:35',0),(7,'PLAN_GEN_FREE_V1','纯大模型方案生成（无候选集约束）','PLAN_GEN_FREE','你是一名企业培训专家。请根据下面的员工技能差距数据，自主设计一份个性化培训方案。\n\n【员工信息】\n姓名：{{realName}}；岗位：{{postName}}；部门：{{deptName}}\n\n【技能差距（已按优先级排序，gap=目标等级-当前等级，priority=gap×权重）】\n{{gapTable}}\n\n【课程库（仅作命名与学时参考，不构成选择限制）】\n{{courseCandidates}}\n\n【知识库依据】\n{{ragContext}}\n\n【要求】\n1. 不限课程范围：可结合岗位要求与技能差距自主判断学什么、先学什么，课程名称可用课程库中的课程，也可按专业判断给出更合适的名称；\n2. 按 gap 从大到小安排学习顺序，先补高权重差距；\n3. 总学时控制在 {{totalHours}} 学时以内，超出视为不合格；\n4. 每门课必须给出 reason，说明它解决哪个技能差距、为什么排在此时；\n5. 学时按经验估计，但需与课程体量相称；\n6. 输出严格为 JSON，不要任何解释性文字或 Markdown 代码块。\n\n【输出格式】\n{\"summary\":\"方案总体说明，150字以内\",\"totalHours\":数字,\"courses\":[{\"courseName\":\"课程名称\",\"hours\":数字,\"reason\":\"安排依据\",\"courseId\":数字}]}','你是企业培训方案设计专家。请根据员工的岗位要求与技能差距，自主设计一份培训方案，包括课程组合、学习顺序与学时安排，并为每门课程说明安排依据。输出必须是合法 JSON，不要输出任何解释性文字、Markdown 代码块或注释。',NULL,NULL,'deepseek-chat',0.30,2000,1,1,'2026-11-25 22:09:09','2026-11-25 22:09:09',0);
/*!40000 ALTER TABLE `ai_prompt_template` ENABLE KEYS */;

--
-- Table structure for table `ai_qa_log`
