DROP TABLE IF EXISTS `ai_qa_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_qa_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `question` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL,
  `answer` text COLLATE utf8mb4_general_ci,
  `ref_chunks` json DEFAULT NULL COMMENT '引用的知识片段ID与相似度',
  `hit_score` decimal(5,4) DEFAULT NULL COMMENT '最高相似度，用于检索质量分析',
  `cost_ms` int DEFAULT NULL,
  `feedback` tinyint DEFAULT NULL COMMENT '用户反馈：1有帮助 0无帮助，用于答案准确率统计',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_create` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='知识问答日志表（检索命中率与答案质量统计）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ai_qa_log`
--

/*!40000 ALTER TABLE `ai_qa_log` DISABLE KEYS */;
INSERT INTO `ai_qa_log` VALUES (1,5,'高处作业安全带应该怎么使用？','（未配置大模型，以下为检索到的原文，供参考）\n\n安全生产规范（安全类，等级 1-5）：掌握作业现场安全规程、劳动防护用品使用与违章行为识别。等级 1 为知晓基本概念；等级 2 为能在指导下完成；等级 3 为能独立完成常规作业；等级 4 为能处理复杂与异常场景并指导他人；等级 5 为能制定标准、开展改进与培训。岗位达标要求由岗位技能要求表确定。','[{\"score\": 1.0, \"chunkId\": 1, \"docName\": \"《安全岗位技能标准》安全生产规范\"}, {\"score\": 0.7699, \"chunkId\": 7, \"docName\": \"《安全岗位技能标准》职业健康防护\"}, {\"score\": 0.7116, \"chunkId\": 3, \"docName\": \"《安全岗位技能标准》危险源辨识与风险评估\"}, {\"score\": 0.6883, \"chunkId\": 5, \"docName\": \"《安全岗位技能标准》应急处置与逃生\"}, {\"score\": 0.6592, \"chunkId\": 44, \"docName\": \"《关键岗位说明书汇编》\"}]',1.0000,3,NULL,'2026-10-17 11:34:28'),(2,1,'新员工入职需要完成哪些必修课？','知识库中未收录“新员工入职必修课”的具体内容。现有片段仅涉及培训需求来源、培训计划分类与状态、岗位技能标准等，未列明新员工入职必修课程。\n\n参考：《员工培训管理办法》《关键岗位说明书汇编》《安全岗位技能标准》《管理岗位技能标准》','[{\"score\": 1.0, \"chunkId\": 41, \"docName\": \"《员工培训管理办法》\"}, {\"score\": 0.7318, \"chunkId\": 42, \"docName\": \"《员工培训管理办法》\"}, {\"score\": 0.624, \"chunkId\": 45, \"docName\": \"《关键岗位说明书汇编》\"}, {\"score\": 0.5717, \"chunkId\": 7, \"docName\": \"《安全岗位技能标准》职业健康防护\"}, {\"score\": 0.4659, \"chunkId\": 37, \"docName\": \"《管理岗位技能标准》现场管理与带教\"}]',1.0000,1785,NULL,'2026-11-25 21:23:35');
/*!40000 ALTER TABLE `ai_qa_log` ENABLE KEYS */;

