DROP TABLE IF EXISTS `course`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `course_code` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程编码',
  `course_name` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程名称',
  `skill_id` bigint DEFAULT NULL COMMENT '主要覆盖技能点',
  `category` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '课程类别',
  `level` int NOT NULL DEFAULT '1' COMMENT '适用等级/难度',
  `duration_hours` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '建议学时',
  `intro` text COLLATE utf8mb4_general_ci COMMENT '课程简介（同时作为知识库语料）',
  `resource_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '课程资源地址',
  `status` tinyint NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_code` (`course_code`),
  KEY `idx_skill` (`skill_id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='课程/培训资源表';
/*!40101 SET character_set_client = @saved_cs_client */;

