INSERT INTO `course` VALUES (1,'C001','安全生产规范基础',1,'安全',1,4.0,'面向安全岗位人员的「安全生产规范」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C001',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(2,'C002','安全生产规范进阶与实战',1,'安全',3,10.0,'在基础之上深入「安全生产规范」的复杂场景处理、异常判断与改进方法，含实操演练与考核。','https://training.example.com/course/C002',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(3,'C003','危险源辨识与风险评估基础',2,'安全',1,6.0,'面向安全岗位人员的「危险源辨识与风险评估」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C003',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(4,'C004','应急处置与逃生基础',3,'安全',1,8.0,'面向安全岗位人员的「应急处置与逃生」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C004',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(5,'C005','应急处置与逃生进阶与实战',3,'安全',3,16.0,'在基础之上深入「应急处置与逃生」的复杂场景处理、异常判断与改进方法，含实操演练与考核。','https://training.example.com/course/C005',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(6,'C006','职业健康防护基础',4,'安全',1,8.0,'面向安全岗位人员的「职业健康防护」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C006',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(7,'C007','设备操作与标准化作业基础',5,'技术',2,8.0,'面向技术岗位人员的「设备操作与标准化作业」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C007',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(8,'C008','设备操作与标准化作业进阶与实战',5,'技术',4,10.0,'在基础之上深入「设备操作与标准化作业」的复杂场景处理、异常判断与改进方法，含实操演练与考核。','https://training.example.com/course/C008',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(9,'C009','设备维护保养基础',6,'技术',2,4.0,'面向技术岗位人员的「设备维护保养」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C009',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(10,'C010','设备故障诊断与排除基础',7,'技术',2,6.0,'面向技术岗位人员的「设备故障诊断与排除」基础课程，覆盖核心概念、操作要求与常见问题，配套案例练习。','https://training.example.com/course/C010',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(11,'C011','设备故障诊断与排除进阶与实战',7,'技术',4,16.0,'在基础之上深入「设备故障诊断与排除」的复杂场景处理、异常判断与改进方法，含实操演练与考核。','https://training.example.com/course/C011',1,'2026-10-17 11:34:21','2026-10-17 11:34:21',0),(12,'