--
-- Table structure for table `effect_eval`
--

DROP TABLE IF EXISTS `effect_eval`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `effect_eval` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `pre_score` decimal(6,1) DEFAULT NULL COMMENT '培训前测成绩',
  `post_score` decimal(6,1) DEFAULT NULL COMMENT '培训后测成绩',
  `score_improve` decimal(6,1) DEFAULT NULL COMMENT '成绩提升值',
  `gap_before` json DEFAULT NULL COMMENT '培训前技能差距快照',
  `gap_after` json DEFAULT NULL COMMENT '培训后技能差距快照',
  `gap_reduce` decimal(6,2) DEFAULT NULL COMMENT '差距缩小率（%）',
  `finish_rate` decimal(5,2) DEFAULT NULL COMMENT '计划完成率（%）',
  `diagnosis` text COLLATE utf8mb4_general_ci COMMENT 'AI 效果诊断结论',
  `retrain_plan` text COLLATE utf8mb4_general_ci COMMENT 'AI 生成的补训方案',
  `eval_result` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '结论：EXCELLENT优秀/PASS达标/FAIL未达标',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_plan_user` (`plan_id`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='培训效果评测表（闭环结果）';
/*!40101 SET character_set_client = @saved_cs_client */;

