--
-- Table structure for table `exam_answer`
--

DROP TABLE IF EXISTS `exam_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exam_answer` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `record_id` bigint NOT NULL,
  `question_id` bigint NOT NULL,
  `user_answer` text COLLATE utf8mb4_general_ci,
  `is_correct` tinyint DEFAULT NULL COMMENT '客观题是否正确',
  `score` decimal(5,1) DEFAULT NULL,
  `ai_score` decimal(5,1) DEFAULT NULL COMMENT '大模型建议分（主观题）',
  `manual_score` decimal(5,1) DEFAULT NULL COMMENT '人工复核分（用于一致性实验）',
  `ai_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '评分理由',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_record` (`record_id`),
  KEY `idx_question` (`question_id`)
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='答题明细表（主观题评分一致性实验的数据来源）';
/*!40101 SET character_set_client = @saved_cs_client */;

