--
-- Table structure for table `kb_doc`
--

DROP TABLE IF EXISTS `kb_doc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kb_doc` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `doc_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '文档名称',
  `doc_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'OTHER' COMMENT '类型：SKILL_STANDARD技能标准/COURSE_OUTLINE课程大纲/POLICY培训制度/POST_DESC岗位说明',
  `source` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源说明（如《国家职业技能标准》），用于方案引用溯源',
  `file_path` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '落库文件路径或原文位置',
  `chunk_count` int NOT NULL DEFAULT '0' COMMENT '切分片段数',
  `status` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'READY' COMMENT '索引状态：PENDING/PROCESSING/READY/FAILED',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_type` (`doc_type`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='知识库文档表';
/*!40101 SET character_set_client = @saved_cs_client */;

