INSERT INTO `plan_course` VALUES (1,1,1,1,8.0,1,2,'安全生产规范为岗位核心要求且当前差距最大，优先安排','2026-10-17 11:34:21','2026-10-17 11:34:21'),(2,1,3,2,8.0,3,2,'应急处置为班组必备能力，紧随安全基础课之后','2026-10-17 11:34:21','2026-10-17 11:34:21'),(3,1,9,3,8.0,5,1,'设备操作差距 1 级，安排在安全类课程之后','2026-10-17 11:34:21','2026-10-17 11:34:21'),(4,2,8,1,10.0,5,3,'该技能当前 1 级、岗位要求 4 级，差 3 级，权重 1.50，加权差距 4.50，在岗位差距中优先级排第 1 位；《设备操作与标准化作业进阶与实战》覆盖等级 4，与目标等级最接近，作为基础补齐课程。','2026-10-17 11:34:26','2026-10-17 11:34:26'),(5,2,7,2,8.0,5,3,'该技能当前 1 级、岗位要求 4 级，差 3 级，权重 1.50，加权差距 4.50，在岗位差距中优先级排第 1 位；《设备操作与标准化作业基础》覆盖等级 2，与目标等级最接近，作为进阶强化课程。','2026-10-17 11:34:26','2026-10-17 11:34:26'),(6,2,27,3,8.0,18,2,'该技能当前 1 级、岗位要求 3 级，差 2 级，权重 0.80，加权差距 1.60，在岗位差距中优先级排第 2 位；《流程制度执行基础》覆盖等级 2，与目标等级最接近，作为针对性补齐课程。','2026-10-17 11:34:26','2026-10-17 11:34:26'),(7,2,2,4,10.0,1,1,'该技能当前 3 级、岗位要求 4 级，差 1 级，权重 1.50，加权差距 1.50，在岗位差距中优先级排第 3 位；《安全生产规范进阶与实战》覆盖等级 3，与目标等级最接近，作为针对性补齐课程。','2026-10-17 11:34:26','2026-10-17 11:34:26'),(8,2,9,5,4.0,6,1,'该技能当前 2 级、岗位要求 3 级，差 1 级，权重 1.00，加权差距 1.00，在岗位差距中优先级排第 4 位；《设备维护保养基础》覆盖等级 2，与目标等级最接近，作为针对性补齐课程。','2026-10-17 11:34:26','2026-10-17 11:34:26'),(9,3,25,1,8.0,NULL,NULL,NULL,'2026-10-24 23:32:03','2026-10-24 23:32:03'),(10,3,30,2,4.0,NULL,NULL,NULL,'2026-10-24 23:32:03','2026-10-24 23:32:03'),(11,3,28,3,6.0,NULL,NULL,NULL,'2026-10-24 23:32:03','2026-10-24 23:32:03'),(12,4,12,1,6.0,NULL,NULL,NULL,'2026-10-24 23:32:04','2026-10-24 23:32:04'),(13,4,13,2,4.0,NULL,NULL,NULL,'2026-10-24 23:32:04','2026-10-24 23:32:04'),(14,4,15,3,6.0,NULL,NULL,NULL,'2026-10-24 23:32:04','2026-10-24 23:32:04'),(15,5,9,1,4.0,NULL,NULL,NULL,'2026-10-24 23:32:07','2026-10-24 23:32:07'),(16,5,10,2,6.0,NULL,NULL,NULL,'2026-10-24 23:32:07','2026-10-24 23:32:07'),(17,5,18,3,6.0,NULL,NULL,NULL,'2026-10-24 23:32:07','2026-10-24 23:32:07'),(18,6,16,1,8.0,NULL,NULL,NULL,'2026-10-24 23:32:09','2026-10-24 23:32:09'),(19,6,19,2,8.0,NULL,NULL,NULL,'2026-10-24 23:32:09','2026-10-24 23:32:09'),(20,6,24,3,6.0,NULL,NULL,NULL,'2026-10-24 23:32:09','2026-10-24 23