DROP TABLE IF EXISTS `question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `skill_id` bigint DEFAULT NULL COMMENT '所属技能点',
  `knowledge_point` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '知识点',
  `question_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '题型：SINGLE单选/MULTI多选/JUDGE判断/SHORT简答',
  `content` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '题干',
  `options` json DEFAULT NULL COMMENT '选项：[{"key":"A","text":"..."}]',
  `answer` text COLLATE utf8mb4_general_ci COMMENT '参考答案',
  `analysis` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '解析',
  `score` decimal(5,1) NOT NULL DEFAULT '5.0' COMMENT '建议分值',
  `difficulty` int NOT NULL DEFAULT '2' COMMENT '难度 1易 2中 3难',
  `gen_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MANUAL' COMMENT '来源：MANUAL人工/AI大模型生成',
