  `skill_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '技能名称',
  `category` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '技能类别：安全/技术/通用/管理',
  `max_level` int NOT NULL DEFAULT '5' COMMENT '等级上限（默认5级）',
  `skill_desc` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '技能说明，用于知识库与Prompt上下文',
