DROP TABLE IF EXISTS `train_need`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `train_need` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `need_title` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '需求标题',
  `dept_id` bigint DEFAULT NULL,
  `post_id` bigint DEFAULT NULL,
  `skill_id` bigint DEFAULT NULL COMMENT '对应技能点',
  `need_desc` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '需求描述',
  `source` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GAP' COMMENT '来源：GAP技能差距自动生成/EMP员工上报/LECTURER讲师提报',
  `priority` int NOT NULL DEFAULT '2' COMMENT '优先级 1高 2中 3低',
  `submitter_id` bigint DEFAULT NULL COMMENT '提报人',
  `audit_status` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '审核状态：PENDING/APPROVED/REJECTED',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_dept_post` (`dept_id`,`post_id`),
  KEY `idx_status` (`audit_status`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='培训需求表';
/*!40101 SET character_set_client = @saved_cs_client */;

