DROP TABLE IF EXISTS `train_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `train_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_no` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `plan_name` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划名称',
  `plan_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型：PERSONAL个人/DEPT部门/POST岗位/BATCH批量',
  `target_user_id` bigint DEFAULT NULL COMMENT '个人计划的目标员工',
  `target_dept_id` bigint DEFAULT NULL COMMENT '部门计划的目标部门',
  `target_post_id` bigint DEFAULT NULL COMMENT '岗位计划的目标岗位',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT草稿/PENDING待审/PUBLISHED已发布/RUNNING进行中/FINISHED已结束/CANCELED已取消',
  `gen_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MANUAL' COMMENT '方案来源：MANUAL人工/AI_RULE规则/AI_LLM大模型/AI_HYBRID规则+大模型',
  `ai_record_id` bigint DEFAULT NULL COMMENT 'AI 生成记录ID（可解释性溯源）',
  `creator_id` bigint DEFAULT NULL,
  `auditor_id` bigint DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL,
  `audit_remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_no` (`plan_no`),
  KEY `idx_target_user` (`target_user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='培训计划表';
/*!40101 SET character_set_client = @saved_cs_client */;

